// version 8:
import lombok.Builder;
import lombok.Value;
import lombok.experimental.SuperBuilder;

@Builder
public class BuilderDefaultsGenericsInference {
	@Builder.Default
	String foo = doSth(MyClass.myInt(), MyClass.myChar());

	@Value
	static class MyClass<T> {
		T value;

		static MyClass<Integer> myInt() {
			return new MyClass<>(42);
		}

		static MyClass<Character> myChar() {
			return new MyClass<>('A');
		}
	}

	@SuperBuilder
	static class SuperBuilderDefault {
		@Builder.Default
		String foo = doSth(MyClass.myInt(), MyClass.myChar());
	}

	static String doSth(MyClass<Integer> i, MyClass<Character> c) {
		return i.value.toString() + c.value.toString();
	}

	public static void main(String[] args) {
		if (!"42A".equals(BuilderDefaultsGenericsInference.builder().build().foo)) throw new AssertionError();
		if (!"override".equals(BuilderDefaultsGenericsInference.builder().foo("override").build().foo)) throw new AssertionError();
		if (BuilderDefaultsGenericsInference.builder().foo(null).build().foo != null) throw new AssertionError();
		if (!"42A".equals(SuperBuilderDefault.builder().build().foo)) throw new AssertionError();
		if (!"override".equals(SuperBuilderDefault.builder().foo("override").build().foo)) throw new AssertionError();
		if (SuperBuilderDefault.builder().foo(null).build().foo != null) throw new AssertionError();
	}
}
